import {catalog,principles,process} from './commercial-data.js';
import {articles} from './articles-data.js';

export function commercialRoute(parts,params,h){
 const {state,e,icon,button,link,money,date,docRows}=h;
 const product=slug=>catalog.find(p=>p.slug===slug);
 const ask=(p,text='Solicitar asesoría')=>link(text,`sitio/nora${p?'?producto='+p.slug:''}`,'primary','arrow');
 const productIndex=()=>`<div class="market-products">${catalog.map(p=>`<a class="market-product" href="#sitio/seguro/${p.slug}"><span class="market-product-icon">${icon(p.icon)}</span><div><h3>${p.title}</h3><p>${p.short}</p></div><span class="market-price">${money(p.price)}<small>Referencia del prototipo</small></span>${icon('arrow')}</a>`).join('')}</div>`;
 const articleIndex=(limit=6)=>`<div class="market-articles">${articles.slice(0,limit).map((a,i)=>`<a href="#sitio/articulo/${i}" class="market-article"><img src="images/article-${i}.jpg" alt="${e(a.images.find(x=>x.alt)?.alt||'Imagen ilustrativa del artículo')}" loading="lazy" width="700" height="460"><p>${e(a.blocks[1]?.text||'Contenido del prototipo')}</p><h3>${e(a.title)}</h3><span>Leer artículo ${icon('arrow')}</span></a>`).join('')}</div>`;
 const cta=(p)=>`<section class="market-cta"><div><h2>${p?`Revisemos tu ${p.title.toLowerCase()}.`:'Tu cotización empieza por una buena conversación.'}</h2><p>Empieza con Nora o prepara una consulta para Víctor. En este demo, todo llega a la mesa de trabajo como una oportunidad ficticia.</p></div>${ask(p,'Empezar con Nora')}</section>`;
 const scopeNote=`<p class="market-note">Contenido adaptado del sitio inicial. Precios, entidades y condiciones son referencias del prototipo, pendientes de confirmar con Víctor. No constituyen oferta ni acreditan alianzas vigentes.</p>`;
 let body='',title='Asesores de Seguros Arias',active=parts[1]||'';
 if(!parts[1]){
 body=`<section class="market-hero"><div class="market-hero-copy"><div class="market-origin">Bogotá · Desde 2008</div><h1>Protegemos lo que <em class="gold-text">más te importa</em></h1><p>Asesoría de seguros con criterio humano y una asistente que te guía paso a paso. Revisamos tus necesidades y comparamos opciones para ayudarte a decidir.</p><div class="actions">${ask(null,'Cotizar con Nora')}${button('Hablar con Víctor','lead-form','','market-light','mail')}</div><div class="market-hero-foot">Bogotá · Confianza, respaldo y experiencia</div></div><img src="images/hero.jpg" alt="Imagen de familia del sitio inicial, utilizada como ilustración" width="1000" height="1050" fetchpriority="high"></section><section class="market-reference-stats"><div><strong>18+</strong><span>Años asesorando</span></div><div><strong>1.400</strong><span>Pólizas vigentes</span></div><div><strong>12</strong><span>Aseguradoras aliadas</span></div><div><strong>24 h</strong><span>Respuesta promedio</span></div><p>Cifras conservadas del demo inicial · Sin verificar</p></section><section class="market-section"><div class="market-heading"><div><h2>Un solo asesor para <em>todos</em> tus riesgos.</h2><p>La protección cambia contigo. El acompañamiento también.</p></div><a href="#sitio/seguros" class="text-link">Ver todos los seguros ${icon('arrow')}</a></div>${productIndex()}${scopeNote}</section><section class="market-process market-section"><div class="market-heading"><div><h2>Nora te lleva de la duda a la <em class="gold-text">propuesta.</em></h2><p>Una conversación clara y un asesor humano para tomar la decisión.</p></div>${ask(null,'Probar el recorrido')}</div><ol>${[['Cuéntale a Nora','Elige qué quieres proteger y comparte una necesidad de muestra.'],['Organiza la información','La solicitud queda lista para revisar datos y documentos.'],['Víctor compara','Un asesor contrasta coberturas, deducibles y exclusiones.'],['Emite y sigue','El expediente conserva vigencias, documentos y próximas gestiones.']].map(([t,d])=>`<li><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol></section><section class="market-about market-section"><img src="images/agency.jpg" alt="Imagen ilustrativa de asesoría del sitio de referencia; no retrata al equipo real" loading="lazy" width="900" height="650"><div><h2>Una agencia pequeña, a propósito.</h2><p>Contestar el teléfono, acompañar el siniestro y explicar cuándo una póliza no te sirve. Ese es el criterio que queremos conservar mientras el negocio crece.</p><blockquote>“Un seguro mal vendido se descubre el día del siniestro. Por eso prefiero explicar las exclusiones antes de firmar, no después.”<cite>Víctor Arias · Texto del sitio inicial</cite></blockquote><a href="#sitio/nosotros" class="text-link">Conocer la agencia ${icon('arrow')}</a></div></section><section class="market-section"><div class="market-heading"><div><h2>Desde el escritorio.</h2><p>Los artículos del sitio inicial, reunidos para revisar y conservar.</p></div><a href="#sitio/blog" class="text-link">Todos los artículos ${icon('arrow')}</a></div>${articleIndex(3)}</section>${cta()}`;
 }else if(parts[1]==='seguros'){
 title='Todos los seguros';body=`<section class="market-section market-intro"><h1>Un solo asesor para todos tus riesgos.</h1><p>Vida, salud, automóvil, hogar, empresa y las demás necesidades de protección que acompañamos.</p>${productIndex()}${scopeNote}</section>${cta()}`;
 }else if(parts[1]==='seguro'){
 const p=product(parts[2]);if(!p)return commercialRoute(['sitio','seguros'],params,h);title=p.title;
 body=`<section class="market-section market-product-intro"><a href="#sitio/seguros" class="back">${icon('left')}Todos los seguros</a><div class="market-product-title"><div><h1>${p.headline}</h1><p>${p.description}</p><div class="actions">${ask(p,'Cotizar '+p.title.toLowerCase())}${button('Preguntar a Víctor','lead-form',p.slug,'','mail')}</div></div><aside><h2>${p.title}</h2><p>Referencia del prototipo</p><strong>${money(p.price)}</strong><small>${p.slug==='viajes'?'Unidad y duración por confirmar':'Por mes · perfil y condiciones por confirmar'}</small><hr><p>Entidades mencionadas en el sitio inicial</p><div class="market-entity-list">${p.entities.map(x=>`<span>${x}</span>`).join('')}</div><small>Listado por validar; sin conexión activa.</small></aside></div></section><section class="market-section market-cover"><h2>Qué cubre</h2><div class="market-cover-grid">${p.cover.map(([t,d])=>`<article><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="market-conditions"><div><h3>Alternativas incluidas según producto</h3><ul>${p.includes.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div><div><h3>Exclusiones y condiciones por revisar</h3><ul>${p.excludes.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div></div>${scopeNote}</section><section class="market-section market-faq"><h2>Preguntas frecuentes</h2>${p.questions.map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</section>${cta(p)}`;
 }else if(parts[1]==='nosotros'){
 title='La agencia';body=`<section class="market-section market-intro"><h1>El criterio de Víctor.<br>Una relación que continúa.</h1><p>Asesores de Seguros Arias & Cía. nació para acompañar decisiones importantes con cercanía. Queremos conservar ese trato mientras organizamos la información y mejoramos el seguimiento.</p><div class="market-principles">${principles.map(([t,d])=>`<article><h2>${t}</h2><p>${d}</p></article>`).join('')}</div></section><section class="market-section"><h2>Cómo trabajamos</h2><ol class="market-working">${process.map(([t,d])=>`<li><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol></section><section class="market-about market-section"><img src="images/agency.jpg" alt="Fotografía ilustrativa de asesoría, procedente del sitio inicial" width="900" height="650"><div><h2>Una conversación directa.</h2><p>Antes de comparar precios, entendemos qué necesitas proteger. Después revisamos las condiciones y acompañamos el proceso.</p><dl class="facts section-space"><div><dt>Ubicación de referencia</dt><dd>Bogotá, D.C. · Colombia</dd></div><div><dt>Correo del sitio inicial</dt><dd>victorarias27@gmail.com</dd></div><div><dt>Teléfono del sitio inicial</dt><dd>311 558 9930</dd></div><div><dt>Dirección por confirmar</dt><dd>Cra. 15 No. 104-33, piso 3</dd></div></dl><div class="actions section-space">${button('Preparar una consulta de muestra','lead-form','','primary','mail')}</div></div></section>${cta()}`;
 }else if(parts[1]==='blog'){
 title='Desde el escritorio';body=`<section class="market-section market-intro"><h1>Lo que deberías saber antes de firmar.</h1><p>Conservamos los seis artículos del sitio inicial. Esta es una edición de trabajo para revisar contenido, autoría y condiciones antes de una publicación futura.</p>${articleIndex()}</section>`;
 }else if(parts[1]==='articulo'){
 const index=Number(parts[2]),a=articles[index];if(!a)return commercialRoute(['sitio','blog'],params,h);title=a.title;let list=false;let blocks='';for(const b of a.blocks.slice(2)){if(b.tag==='li'){if(!list){blocks+='<ul>';list=true;}blocks+=`<li>${e(b.text)}</li>`;}else{if(list){blocks+='</ul>';list=false;}blocks+=`<${b.tag==='h2'?'h2':'p'}>${e(b.text)}</${b.tag==='h2'?'h2':'p'}>`;}}if(list)blocks+='</ul>';
 body=`<article class="market-section market-reading"><a href="#sitio/blog" class="back">${icon('left')}Volver al blog</a><h1>${e(a.title)}</h1><p class="market-article-deck">${e(a.blocks[0]?.text)}</p><p class="market-byline">${e(a.blocks[1]?.text)} · Contenido del prototipo inicial, pendiente de revisión</p><img class="market-reading-img" src="images/article-${index}.jpg" alt="${e(a.images.find(i=>i.alt)?.alt||'Imagen ilustrativa del artículo')}" width="1400" height="750"><div class="market-reading-text">${blocks}</div><div class="callout info section-space">${icon('info')}<p>Texto conservado de la referencia por solicitud de la familia. Las afirmaciones, ejemplos, precios y requisitos requieren revisión editorial y técnica antes de su uso público.</p></div><div class="actions section-space">${ask(null,'Consultar con Nora')}${link('Volver a los artículos','sitio/blog')}</div></article>`;
 }else if(parts[1]==='nora'){
 const p=product(params.get('producto'));title='Nora · Asesoría guiada';body=`<section class="market-section market-nora"><div><h1>Hola. Soy Nora.<br>¿Qué quieres proteger?</h1><p>Vamos a organizar tu solicitud con unas preguntas cortas. Un asesor revisaría después la información y las opciones disponibles.</p><ul class="checklist section-space"><li>${icon('check')}La información se captura una sola vez.</li><li>${icon('check')}La oportunidad entra a la mesa de trabajo.</li><li>${icon('check')}El asesor conserva el criterio y la recomendación.</li></ul><p class="market-note">Nora es un flujo guiado de demostración. No consulta aseguradoras ni calcula una prima real.</p></div><form id="commercial-lead" class="market-nora-form"><h2>Tu solicitud de muestra</h2><div class="field-group"><label for="nora-product">¿Qué necesitas proteger?</label><select id="nora-product" name="product">${catalog.map(x=>`<option value="${e(x.product)}" ${x.slug===p?.slug?'selected':''}>${x.title}</option>`).join('')}</select></div><div class="field-group"><label for="nora-need">Cuéntanos la necesidad</label><textarea id="nora-need" name="need" rows="3" required maxlength="1500" placeholder="Por ejemplo: quiero revisar las opciones para renovar mi automóvil…"></textarea></div><div class="field-group"><label for="nora-when">¿En qué momento estás?</label><select id="nora-when" name="moment"><option>Mi póliza vence pronto</option><option>Es una protección nueva</option><option>Quiero revisar lo que ya tengo</option></select></div><div class="form-grid"><div><label for="nora-name">Nombre ficticio</label><input id="nora-name" name="name" value="Mariana del Valle" required maxlength="100"></div><div><label for="nora-email">Correo de muestra</label><input id="nora-email" name="email" type="email" value="mariana@example.com" required></div></div><label class="request-check section-space"><input type="checkbox" required><span>Estoy usando datos ficticios para probar el recorrido.</span></label><input type="hidden" name="source" value="Nora · sitio comercial demo"><button type="submit" class="btn primary">Preparar solicitud de prueba ${icon('arrow')}</button><p class="error-message" role="alert"></p></form></section>`;
 }else if(parts[1]==='gracias'){
 const l=state.leads.find(x=>x.id===parts[2]);title='Solicitud registrada';body=`<section class="market-section market-success">${icon('check','icon-large')}<h1>La conversación ya tiene un lugar.</h1><p>${l?`La solicitud ficticia de ${e(l.name)} sobre ${e(l.product.toLowerCase())} quedó registrada con su origen comercial.`:'La solicitud de muestra está en la mesa de trabajo.'} Ahora puedes ver cómo continúa el seguimiento.</p><div class="actions">${link('Ver oportunidad en la aplicación','oportunidades','primary','arrow')}${link('Volver al sitio','sitio')}</div></section>`;
 }else if(parts[1]==='portal'){
 const cl=state.clients.find(c=>c.id==='c01'),ps=state.policies.filter(p=>p.clientId===cl.id);title='Portal de cliente · muestra';body=`<section class="market-section market-portal"><div class="callout info">${icon('info')}<div><strong>Vista de cliente ficticia · Elena Montes</strong><p>Esta pantalla ilustra la consulta futura. No hay autenticación ni control de acceso de producción.</p></div></div><div class="market-heading"><div><h1>Tus seguros, a la mano.</h1><p>Vigencias y documentos del expediente ficticio de Elena.</p></div>${link('Ver desde la aplicación interna','cliente/c01','','arrow')}</div>${ps.map(p=>`<article class="market-portal-policy"><div>${icon(p.product==='Automóvil'?'car':'shield')}<h2>${e(p.product)}</h2><p>${e(p.number)} · ${e(p.insurer)} simulada</p></div><dl class="facts"><div><dt>Desde</dt><dd>${date(p.start)}</dd></div><div><dt>Hasta</dt><dd>${date(p.end)}</dd></div><div><dt>Prima anual ilustrativa · COP</dt><dd>${money(p.premium)}</dd></div></dl>${button('Consultar documento','document',p.docId,'','file')}</article>`).join('')}<section class="section-space"><h2>Documentos disponibles</h2>${docRows(state.documents.filter(d=>d.clientId===cl.id))}</section></section>`;
 }else{return commercialRoute(['sitio'],params,h);}
 const html=`<div class="market ${!parts[1]?'market-home':''}"><div class="market-mode"><span>Demo · Datos ficticios</span><a href="#inicio">Abrir mesa de trabajo ${icon('arrow')}</a></div><header class="market-header"><a href="#sitio" class="brand market-brand" aria-label="Arias, sitio comercial"><img class="market-monogram" src="images/arias-monogram.svg" alt="" width="44" height="44"><span class="market-wordmark">Asesores de Seguros<small>Arias &amp; Cía. Ltda.</small></span></a><nav aria-label="Navegación del sitio comercial"><a href="#sitio/seguros" ${active==='seguros'||active==='seguro'?'aria-current="page"':''}>Seguros</a><a href="#sitio/nosotros" ${active==='nosotros'?'aria-current="page"':''}>Nosotros</a><a href="#sitio/blog" ${active==='blog'||active==='articulo'?'aria-current="page"':''}>Desde el escritorio</a><a href="#sitio/portal">Mis pólizas</a></nav>${ask(null,'Cotizar con Nora')}</header><main id="main" tabindex="-1">${body}</main><footer class="market-footer"><div><a href="#sitio" class="brand market-brand"><img class="market-monogram" src="images/arias-monogram.svg" alt="" width="44" height="44"><span class="market-wordmark">Asesores de Seguros<small>Arias &amp; Cía. Ltda.</small></span></a><p>Protegemos lo que más te importa.</p><small>Confianza · Respaldo · Experiencia</small></div><div><h2>Seguros</h2>${catalog.map(p=>`<a href="#sitio/seguro/${p.slug}">${p.title}</a>`).join('')}</div><div><h2>La agencia</h2><a href="#sitio/nosotros">Nosotros</a><a href="#sitio/blog">Desde el escritorio</a><a href="#sitio/nora">Cotizar con Nora</a><a href="#sitio/portal">Portal de muestra</a><a href="#inicio">Mesa de trabajo</a></div><div><h2>Contacto de referencia</h2><p>Bogotá, D.C. · Colombia<br>311 558 9930<br>victorarias27@gmail.com</p>${button('Preparar consulta ficticia','lead-form','','market-light small')}</div><p class="market-footer-note">Demostración del proyecto · Contenido conservado y adaptado de asesores-arias.pages.dev · Fotografías ilustrativas de Unsplash procedentes del sitio inicial · Datos, precios y conexiones de demostración. No se envía información.</p></footer></div>`;
 return {html,title};
}
